{
  "$schema": "https://opencode.ai/config.json",
  "permission": {
    "bash": {
      "*": "ask",
      "git *": "allow",
      "git push *": "deny",
      "npm *": "allow",
      "yarn *": "allow",
      "go *": "allow",
      "flutter *": "allow",
      "grep *": "allow",
      "sort *": "allow",
      "mkdir *": "allow",
      "ls *": "allow",
      "find *": "allow",
      "tree *": "allow",
      "head *": "allow",
      "tail *": "allow",
      "pwd": "allow",
      "realpath *": "allow",
      "cat *": "allow",
      "touch *": "allow",
      "cd *": "allow",
      "sed *": "allow",
      "echo *": "allow",
      "jq *": "allow",
      "wc *": "allow",
      "rtk *": "allow",
      "rtk rm *": "ask",
      "rtk git push *": "deny"
    },
    "edit": {
      "/home/hbollon/git/*": "allow",
      "/tmp/*": "allow",
      "/*": "ask"
    },
    "question": "allow"
  },
  "plugin": [
    ["@plannotator/opencode@latest", {
      "workflow": "plan-agent",
      "planningAgents": ["plan", "orchestrator"]
    }],
    "@tarquinen/opencode-dcp@latest",
    "oh-my-opencode-slim@latest"
  ],
  "mcp": {
    "context7": {
      "type": "remote",
      "url": "https://mcp.context7.com/mcp",
      "enabled": true,
      "headers": {
        "CONTEXT7_API_KEY": "${CONTEXT7_API_KEY}"
      }
    },
    "stitch": {
      "type": "remote",
      "url": "https://stitch.googleapis.com/mcp",
      "headers": {
        "X-Goog-Api-Key": "${STITCH_API_KEY}"
      }
    }
  },
  "agent": {
    "explore": {
      "disable": true
    },
    "general": {
      "disable": true
    }
  },
  "skills": {
    "paths": ["skills-ext"]
  }
}

{
  "dependencies": {
    "@opencode-ai/plugin": "1.14.20"
  }
}
